extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return
	var overview := find_by_name(main, "CameraOverview") as Camera3D
	var west := find_by_name(main, "CameraWest") as Camera3D
	var east := find_by_name(main, "CameraEast") as Camera3D
	var label := find_by_name(main, "CrystalLabel") as Label
	var crystal := find_by_name(main, "Crystal") as Node3D
	if not check("cameras", overview != null and west != null and east != null, "Le tre telecamere devono essere presenti nella scena"):
		return
	if not check("nodes", label != null and crystal != null, "CrystalLabel e Crystal devono essere presenti nella scena"):
		return
	var active_cam := main.get_viewport().get_camera_3d()
	check("start_cam", active_cam == overview, "All'avvio la telecamera attiva deve essere CameraOverview")
	await tap_action("change_atmosphere")
	await wait_frames(2)
	active_cam = main.get_viewport().get_camera_3d()
	check("second_cam", active_cam == west, "Premendo il tasto di cambio telecamera si passa a CameraWest")
	await tap_action("change_atmosphere")
	await wait_frames(2)
	active_cam = main.get_viewport().get_camera_3d()
	check("third_cam", active_cam == east, "Premendo nuovamente il tasto si passa a CameraEast")
	if active_cam != null and crystal != null and label != null:
		var expected_behind := active_cam.is_position_behind(crystal.global_position)
		if expected_behind:
			check("label_hidden", not label.visible, "Se il cristallo è dietro la telecamera, CrystalLabel deve essere nascosta")
		else:
			var expected_pos := active_cam.unproject_position(crystal.global_position) + Vector2(-25.0, -30.0)
			check("label_pos", label.position.distance_to(expected_pos) < 5.0, "CrystalLabel deve posizionarsi su unproject_position del cristallo con offset Vector2(-25.0, -30.0)")

